            </div>
            <div class="bg-gray-100 p-4 rounded-md">
                <button type="submit" onclick="submitForm()" class="bg-blue-500 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded-lg">Submit</button>
            </div>
        </div>
    </div>
    <div class="bg-gray-100 font-roboto">
        <div class="max-w-xl mx-auto py-12 px-4 sm:px-6 lg:px-2">
            <div class="mt-8" id="scheduleContainer">
                <!-- Schedule will be dynamically populated here -->
            </div>
        </div>
    </div>

    <script>
        // Configuration
        const CONFIG = {
            apiEndpoint: 'https://busapi.amithv.xyz/api/v1/schedules'
        };

        // DOM Elements
        const elements = {
            departure: document.getElementById('departure'),
            destination: document.getElementById('destination'),
            time: document.getElementById('time'),
            scheduleContainer: document.getElementById('scheduleContainer')
        };

        // State management
        const state = {
            scheduleData: [],
            isLoading: false
        };

        // Utility functions
        const utils = {
            createElement: (template) => {
                const temp = document.createElement('div');
                temp.innerHTML = template.trim();
                return temp.firstChild;
            },
            setStatusMessage: (message, isError = false) => {
                const statusMessage = document.createElement('div');
                statusMessage.className = `p-3 rounded-md ${isError ? 'bg-red-100 text-red-800' : 'bg-green-100 text-green-800'}`;
                statusMessage.textContent = message;
                return statusMessage;
            }
        };

        // API functions
        const api = {
            fetchSchedule: async (departure, destination, time) => {
                try {
                    state.isLoading = true;
                    const response = await fetch(`${CONFIG.apiEndpoint}?departure=${encodeURIComponent(departure)}&destination=${encodeURIComponent(destination)}&time=${encodeURIComponent(time)}`);
                    if (!response.ok) throw new Error('Network response was not ok');
                    return await response.json();
                } catch (error) {
                    console.error("Error fetching data:", error);
                    return [];
                } finally {
                    state.isLoading = false;
                }
            }
        };

        // Render functions
        const render = {
            schedule: (scheduleData) => {
                elements.scheduleContainer.innerHTML = '';

                if (scheduleData.length === 0) {
                    elements.scheduleContainer.appendChild(utils.createElement('<div class="text-center py-8">No schedule found</div>'));
                    return;
                }

                scheduleData.forEach(trip => {
                    const vehicleDiv = utils.createElement(`
                        <div class="mb-4">
                            <div class="font-medium text-lg mb-2">Vehicle: ${trip.vehicle_number}, Trip: ${trip.trip}</div>
                            <div class="flex flex-col space-y-2">
                                ${trip.stations.map(station => {
                                    const hasDeparted = station.station.toUpperCase().startsWith(elements.departure.value.toUpperCase());
                                    const hasArrived = station.station.toUpperCase().startsWith(elements.destination.value.toUpperCase());

                                    return `
                                        <div class="station">
                                            ${hasDeparted ? utils.createElement('<div class="timeline green-line"></div>') : utils.createElement('<div class="timeline"></div>')}
                                            <div class="time-wrapper">
                                                <div class="hoi ${hasDeparted && !hasArrived ? 'green-border' : ''}"></div>
                                                <div class="station-time ${hasDeparted && !hasArrived ? 'green-bg' : ''}">${station.arrivalTime}</div>
                                            </div>
                                            <div class="station-name">${station.station}</div>
                                            <div class="time-wrapper">
                                                <div class="hoi ${hasDeparted && !hasArrived ? 'green-border' : ''}"></div>
                                                <div class="station-time ${hasDeparted && !hasArrived ? 'green-bg' : ''}">${station.departureTime}</div>
                                            </div>
                                        </div>
                                    `;
                                }).join('')}
                            </div>
                        </div>
                    `);

                    elements.scheduleContainer.appendChild(vehicleDiv);
                });
            }
        };

        // Event handlers
        const handlers = {
            handleFormSubmit: async (e) => {
                e.preventDefault();

                const departure = elements.departure.value.trim();
                const destination = elements.destination.value.trim();
                const time = elements.time.value;

                if (!departure || !destination || !time) {
                    alert('Please fill in all fields');
                    return;
                }

                try {
                    const data = await api.fetchSchedule(departure, destination, time);
                    render.schedule(data);
                } catch (error) {
                    alert('Failed to fetch schedule data');
                }
            }
        };

        // Initialize
        document.addEventListener('DOMContentLoaded', () => {
            document.querySelector('form').addEventListener('submit', handlers.handleFormSubmit);
        });
    </script>
</body>
</html>
